      "c": "#include <stdio.h>\n#include <string.h>\n\nint main() {\n    const char *records[5][3] = {\n        {\"A-17\", \"SECURITY\", \"ANALYST\"},\n        {\"S-04\", \"NETWORK\", \"ENGINEER\"},\n        {\"C-21\", \"CRYPTO\", \"RESEARCHER\"},\n        {\"S-00\", \"SYSTEMS\", \"ARCHITECT\"},\n        {\"N-12\", \"NETWORK\", \"ADMIN\"}\n    };\n\n    char subject[32] = \"\";\n    char role[32] = \"\";\n\n    for (int i = 0; i < 5; i++) {\n        const char *id = records[i][0];\n        const char *department = records[i][1];\n        const char *position = records[i][2];\n\n        if (strcmp(id, \"S-00\") == 0) {\n            strcpy(subject, \"SUBJECT 0\");\n        }\n\n        if (strcmp(id, \"S-00\") == 0 && strcmp(department, \"SYSTEMS\") == 0) {\n            sprintf(role, \"SYSTEMS %s\", position);\n        }\n    }\n\n    printf(\"%s\\n\", subject);\n    printf(\"%s\\n\", role);\n    return 0;\n}",
