      "java": "public class LocationReconstruction {\n    public static void main(String[] args) {\n        int[] timestamp = {3, 17, 42};\n        int[] erased = {702, 705, 706};\n        int[] fragments = {1, 2, 3, 4, 5, 6, 7, 8, 9};\n\n        int seed = timestamp[0] + timestamp[1] + erased.length;\n        seed = seed + fragments.length;\n\n        String[] route = {\n            \"NODE-07\",\n            \"NODE-12\",\n            \"NODE-04\",\n            \"NODE-19\",\n            \"NODE-03\",\n            \"NODE-21\",\n            \"NODE-00\"\n        };\n\n        int index = seed % route.length;\n        String current = \"\";\n\n        for (int i = 0; i <= index; i++) {\n            current = route[i];\n        }\n\n        System.out.println(current);\n    }\n}",
      "c": "#include <stdio.h>\n\nint main() {\n    int timestamp[] = {3, 17, 42};\n    int erased[] = {702, 705, 706};\n    int fragments[] = {1, 2, 3, 4, 5, 6, 7, 8, 9};\n\n    int erased_len = 3;\n    int frag_len = 9;\n\n    int seed = timestamp[0] + timestamp[1] + erased_len;\n    seed = seed + frag_len;\n\n    const char *route[] = {\n        \"NODE-07\",\n        \"NODE-12\",\n        \"NODE-04\",\n        \"NODE-19\",\n        \"NODE-03\",\n        \"NODE-21\",\n        \"NODE-00\"\n    };\n\n    int route_len = 7;\n    int index = seed % route_len;\n    const char *current = \"\";\n\n    for (int i = 0; i <= index; i++) {\n        current = route[i];\n    }\n\n    printf(\"%s\\n\", current);\n    return 0;\n}",
      "cpp": "#include <iostream>\n#include <vector>\n#include <string>\n\nint main() {\n    std::vector<int> timestamp = {3, 17, 42};\n    std::vector<int> erased = {702, 705, 706};\n    std::vector<int> fragments = {1, 2, 3, 4, 5, 6, 7, 8, 9};\n\n    int seed = timestamp[0] + timestamp[1] + erased.size();\n    seed = seed + fragments.size();\n\n    std::vector<std::string> route = {\n        \"NODE-07\",\n        \"NODE-12\",\n        \"NODE-04\",\n        \"NODE-19\",\n        \"NODE-03\",\n        \"NODE-21\",\n        \"NODE-00\"\n    };\n\n    int index = seed % route.size();\n    std::string current = \"\";\n\n    for (int i = 0; i <= index; i++) {\n        current = route[i];\n    }\n\n    std::cout << current << std::endl;\n    return 0;\n}"
